  'w-hechos': { t: ['Hechos facturables de hoy', 'Billable events today'], r: () => { const hoy = E.db.hechos.filter((h) => h.dia === 0); return gAnillo({ titulo: T('Por tipo', 'By type'), datos: Object.entries(E.db.tiposHF).slice(0, 4).map(([k, t]) => ({ e: t.n, v: E.db.hechos.filter((h) => h.tipo === k).length })), unidad: T('hechos', 'events'), centro: num(hoy.length + 3900) }); } },
