ACC['tablero-pers'] = () => { E.ui.personalizar = !E.ui.personalizar; refrescar(); $('#b-pers')?.focus(); };
ACC['tablero-restaurar'] = async () => { if (!(await confirmar({ titulo: T('¿Restaurar el tablero?', 'Restore the dashboard?'), texto: T('Vuelven los componentes y el orden iniciales de tu perfil.', 'Your profile default widgets and order come back.'), si: T('Restaurar', 'Restore') }))) return; delete E.ui.tablero[E.sesion.perfil]; aviso(T('Tablero restaurado.', 'Dashboard restored.')); refrescar(); $('#b-pers')?.focus(); };
ACC['tablero-agregar'] = () => { const id = $('#w-agregar').value; tableroDe(E.sesion.perfil).push({ id, t: 1 }); aviso(T(`Agregado: ${ES(WIDGETS[id].t)}.`, `Added: ${ES(WIDGETS[id].t)}.`)); refrescar(); $('#b-agregar')?.focus() || $('#b-pers')?.focus(); };
ACC['w-mover'] = (el) => { const [i, d] = el.dataset.arg.split('|').map(Number); const tb = tableroDe(E.sesion.perfil); const j = i + d; if (j < 0 || j >= tb.length) return; [tb[i], tb[j]] = [tb[j], tb[i]]; const id = tb[j].id; anunciar(T(`${ES(WIDGETS[id].t)}: ahora en la posición ${j + 1} de ${tb.length}.`, `${ES(WIDGETS[id].t)}: now at position ${j + 1} of ${tb.length}.`)); refrescar(); (document.getElementById(`wm-${id}-${d < 0 ? 'a' : 'd'}`)?.disabled ? document.getElementById(`wm-${id}-${d < 0 ? 'd' : 'a'}`) : document.getElementById(`wm-${id}-${d < 0 ? 'a' : 'd'}`))?.focus(); };
ACC['w-quitar'] = (el) => { const tb = tableroDe(E.sesion.perfil); const [w] = tb.splice(Number(el.dataset.arg), 1); aviso(T(`Quitado: ${ES(WIDGETS[w.id].t)}. Puedes volver a agregarlo.`, `Removed: ${ES(WIDGETS[w.id].t)}. You can add it back.`)); refrescar(); $('#b-pers')?.focus(); };
CAMBIO['w-tam'] = (el) => { tableroDe(E.sesion.perfil)[Number(el.dataset.arg)].t = Number(el.value); refrescar(); };

